<?php
namespace App\Domain\Clients; use App\Domain\Homepage\HomepageCache; use App\Domain\PublicChrome\PublicChromeCache; use App\Models\{HomepageItem,NavigationItem}; use Illuminate\Support\Facades\Cache; use Throwable; final class ClientCache { public static function version(int $id):int{try{return (int)Cache::rememberForever("public.clients.version.$id",fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}} public static function indexVersion():int{try{return (int)Cache::rememberForever('public.clients.index.version',fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}} public static function forget(int $id):void{try{Cache::put("public.clients.version.$id",hrtime(true));Cache::put('public.clients.index.version',hrtime(true));if(HomepageItem::where('client_id',$id)->exists())HomepageCache::forget();if(NavigationItem::where('client_id',$id)->exists())PublicChromeCache::forgetAll();}catch(Throwable){}} }
